-- ============================================================================
-- API migrations
-- ============================================================================

-- ---- apps/api/migrations/001_init.sql
-- Helix initial schema.
--
-- Postgres backs everything: API keys, jobs, results, crawl state, monitors and
-- vectors. One datastore means no Redis, no RabbitMQ, and no boot race — which is
-- the single most-cited self-host complaint about comparable tools.

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
-- pgvector is optional: the chunks table below is created only when the extension
-- is available, so a Postgres without it still boots (the pgvector sink reports unavailable).
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'vector') THEN
    CREATE EXTENSION IF NOT EXISTS vector;
  END IF;
END $$;

-- ---------------------------------------------------------------- auth

-- Helix API keys authenticate a caller to this instance. They are unrelated to
-- the operator's LLM/proxy/vector credentials, which live in the environment and
-- never touch the database.
CREATE TABLE IF NOT EXISTS api_keys (
  id           uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  name         text        NOT NULL,
  key_hash     text        NOT NULL UNIQUE,   -- sha256; the key itself is shown once, at creation
  key_prefix   text        NOT NULL,          -- first 8 chars, for display: hx_a1b2c3d4…
  rate_limit   integer     NOT NULL DEFAULT 1000,
  created_at   timestamptz NOT NULL DEFAULT now(),
  last_used_at timestamptz,
  revoked_at   timestamptz
);

CREATE INDEX IF NOT EXISTS api_keys_active ON api_keys (key_hash) WHERE revoked_at IS NULL;

-- ---------------------------------------------------------------- jobs

DO $do$ BEGIN
  CREATE TYPE job_type AS ENUM ('crawl', 'batch_scrape', 'enrich', 'monitor_check');
EXCEPTION WHEN duplicate_object THEN NULL;
END $do$;
DO $do$ BEGIN
  CREATE TYPE job_status AS ENUM ('queued', 'running', 'completed', 'failed', 'cancelled');
EXCEPTION WHEN duplicate_object THEN NULL;
END $do$;

CREATE TABLE IF NOT EXISTS jobs (
  id           uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  api_key_id   uuid        REFERENCES api_keys(id) ON DELETE SET NULL,
  type         job_type    NOT NULL,
  status       job_status  NOT NULL DEFAULT 'queued',
  request      jsonb       NOT NULL,
  total        integer     NOT NULL DEFAULT 0,
  completed    integer     NOT NULL DEFAULT 0,
  failed       integer     NOT NULL DEFAULT 0,
  usage        jsonb       NOT NULL DEFAULT '{}',
  error        text,
  created_at   timestamptz NOT NULL DEFAULT now(),
  started_at   timestamptz,
  finished_at  timestamptz,
  expires_at   timestamptz NOT NULL DEFAULT now() + interval '7 days'
);

CREATE INDEX IF NOT EXISTS jobs_status_created ON jobs (status, created_at);
CREATE INDEX IF NOT EXISTS jobs_expiry         ON jobs (expires_at);

-- The work queue. Claimed with SELECT … FOR UPDATE SKIP LOCKED, which gives
-- multi-worker safety without a separate broker.
CREATE TABLE IF NOT EXISTS job_tasks (
  id            bigserial PRIMARY KEY,
  job_id        uuid        NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  url           text        NOT NULL,
  depth         integer     NOT NULL DEFAULT 0,
  status        job_status  NOT NULL DEFAULT 'queued',
  attempts      integer     NOT NULL DEFAULT 0,
  -- hash(normalised url + render params + profile + proxy geo + schema version).
  -- The queue is honestly at-least-once, so side effects must be idempotent.
  idempotency_key text      NOT NULL,
  claimed_at    timestamptz,
  claimed_by    text,
  available_at  timestamptz NOT NULL DEFAULT now(),
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS job_tasks_claimable ON job_tasks (status, available_at) WHERE status = 'queued';
CREATE INDEX IF NOT EXISTS job_tasks_job       ON job_tasks (job_id, status);
CREATE UNIQUE INDEX IF NOT EXISTS job_tasks_idem ON job_tasks (job_id, idempotency_key);

-- ---------------------------------------------------------------- results

CREATE TABLE IF NOT EXISTS documents (
  id           uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  job_id       uuid        REFERENCES jobs(id) ON DELETE CASCADE,
  url          text        NOT NULL,
  final_url    text,
  content_hash text        NOT NULL,   -- sha256 of normalised content; drives incremental crawl
  status_code  integer,
  content_type text,
  tier         text        NOT NULL,   -- which fetch tier ultimately succeeded
  profile      text,
  content      jsonb       NOT NULL,   -- markdown, html, json, chunks …
  metadata     jsonb       NOT NULL DEFAULT '{}',
  fetched_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz NOT NULL DEFAULT now() + interval '7 days'
);

CREATE INDEX IF NOT EXISTS documents_job     ON documents (job_id);
CREATE INDEX IF NOT EXISTS documents_url     ON documents (url);
CREATE INDEX IF NOT EXISTS documents_hash    ON documents (content_hash);
CREATE INDEX IF NOT EXISTS documents_expiry  ON documents (expires_at);

-- Typed failures. A bot challenge returning HTTP 200 is recorded here, never as a
-- document — the whole point is that a block page is never mistaken for content.
CREATE TABLE IF NOT EXISTS fetch_failures (
  id            bigserial PRIMARY KEY,
  job_id        uuid        REFERENCES jobs(id) ON DELETE CASCADE,
  url           text        NOT NULL,
  reason        text        NOT NULL,   -- blocked | challenge | timeout | dns | tls | http_error | empty | robots_denied
  detail        text,
  status_code   integer,
  detected_by   text[],                 -- which signals fired
  tier          text,
  tiers_tried   text[],
  profile       text,
  escalation_available boolean NOT NULL DEFAULT false,
  occurred_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS fetch_failures_job ON fetch_failures (job_id);

-- ---------------------------------------------------------------- crawl state

-- Per-site memory so incremental re-crawls can skip unchanged pages, and so a
-- restart resumes a frontier rather than restarting it.
CREATE TABLE IF NOT EXISTS crawl_state (
  id            bigserial PRIMARY KEY,
  site          text        NOT NULL,   -- eTLD+1
  url           text        NOT NULL,
  content_hash  text,
  last_modified timestamptz,
  etag          text,
  last_seen_at  timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS crawl_state_url ON crawl_state (url);
CREATE INDEX IF NOT EXISTS crawl_state_site       ON crawl_state (site);

-- ---------------------------------------------------------------- monitors

CREATE TABLE IF NOT EXISTS monitors (
  id              uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  api_key_id      uuid        REFERENCES api_keys(id) ON DELETE CASCADE,
  urls            text[]      NOT NULL,
  schedule        jsonb       NOT NULL,
  diff_config     jsonb       NOT NULL DEFAULT '{}',
  trigger_config  jsonb       NOT NULL DEFAULT '{}',
  scrape_options  jsonb       NOT NULL DEFAULT '{}',
  webhook         jsonb,
  status          text        NOT NULL DEFAULT 'active',
  created_at      timestamptz NOT NULL DEFAULT now(),
  last_checked_at timestamptz,
  next_check_at   timestamptz,
  checks          integer     NOT NULL DEFAULT 0,
  changes         integer     NOT NULL DEFAULT 0,
  pages_unchanged integer     NOT NULL DEFAULT 0   -- unchanged pages cost nothing
);

CREATE INDEX IF NOT EXISTS monitors_due ON monitors (next_check_at) WHERE status = 'active';

CREATE TABLE IF NOT EXISTS monitor_snapshots (
  id           bigserial PRIMARY KEY,
  monitor_id   uuid        NOT NULL REFERENCES monitors(id) ON DELETE CASCADE,
  url          text        NOT NULL,
  content_hash text        NOT NULL,
  content      text,
  captured_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS monitor_snapshots_lookup ON monitor_snapshots (monitor_id, url, captured_at DESC);

-- ---------------------------------------------------------------- webhooks

-- Stripe-shaped delivery: exponential backoff over days, then a dead letter you
-- can replay. Not three retries over twenty minutes.
CREATE TABLE IF NOT EXISTS webhook_deliveries (
  id            bigserial PRIMARY KEY,
  job_id        uuid        REFERENCES jobs(id) ON DELETE CASCADE,
  monitor_id    uuid        REFERENCES monitors(id) ON DELETE CASCADE,
  url           text        NOT NULL,
  event_type    text        NOT NULL,
  payload       jsonb       NOT NULL,
  -- dedupe key: (job, event, url) — the queue is at-least-once
  dedupe_key    text        NOT NULL,
  attempts      integer     NOT NULL DEFAULT 0,
  status        text        NOT NULL DEFAULT 'pending',  -- pending | delivered | dead
  last_error    text,
  next_retry_at timestamptz NOT NULL DEFAULT now(),
  created_at    timestamptz NOT NULL DEFAULT now(),
  delivered_at  timestamptz
);

CREATE UNIQUE INDEX IF NOT EXISTS webhook_deliveries_dedupe ON webhook_deliveries (dedupe_key);
CREATE INDEX IF NOT EXISTS webhook_deliveries_pending ON webhook_deliveries (next_retry_at) WHERE status = 'pending';

-- ---------------------------------------------------------------- vectors

-- pgvector sink. Point IDs are deterministic (UUID v5 from the URL) so a re-crawl
-- updates in place instead of duplicating vectors.
-- 384 is the default local model's embedding dimension; other dimensions need
-- an ALTER COLUMN embedding TYPE vector(N) after this migration runs.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'vector') THEN
    EXECUTE $sql$CREATE TABLE IF NOT EXISTS chunks (
  id          uuid PRIMARY KEY,
  document_id uuid        REFERENCES documents(id) ON DELETE CASCADE,
  collection  text        NOT NULL DEFAULT 'default',
  url         text        NOT NULL,
  anchor      text        NOT NULL,   -- stable across re-crawls, so citations keep resolving
  text        text        NOT NULL,
  tokens      integer,
  embedding   vector(384),
  metadata    jsonb       NOT NULL DEFAULT '{}',
  created_at  timestamptz NOT NULL DEFAULT now()
)$sql$;
    EXECUTE $sql$CREATE INDEX IF NOT EXISTS chunks_collection ON chunks (collection)$sql$;
    EXECUTE $sql$CREATE INDEX IF NOT EXISTS chunks_url        ON chunks (url)$sql$;
    EXECUTE $sql$CREATE INDEX IF NOT EXISTS chunks_embedding  ON chunks USING hnsw (embedding vector_cosine_ops)$sql$;
  END IF;
END $$;

-- ---------------------------------------------------------------- enrichment

CREATE TABLE IF NOT EXISTS enrich_results (
  id         bigserial PRIMARY KEY,
  job_id     uuid        NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  row_index  integer     NOT NULL,
  input      jsonb       NOT NULL,
  -- Each field carries value, confidence, and the passage that grounded it.
  -- A null value carries a reason: no sources, conflicting sources, low confidence.
  fields     jsonb       NOT NULL DEFAULT '{}',
  status     text        NOT NULL DEFAULT 'completed',
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS enrich_results_job ON enrich_results (job_id, row_index);

-- ---- apps/api/migrations/002_frontier.sql
-- Frontier persistence and incremental crawl.
--
-- 001 shipped a `job_tasks` table but the worker kept its queue in memory, so a
-- restart mid-crawl lost the frontier and began again. These changes make the
-- queue durable and let a re-crawl skip pages that have not changed.

-- The frontier needs the depth and the politeness partition alongside the URL,
-- so a resuming worker can rebuild its state without re-deriving them.
ALTER TABLE job_tasks ADD COLUMN IF NOT EXISTS site text;
ALTER TABLE job_tasks ADD COLUMN IF NOT EXISTS discovered_at timestamptz NOT NULL DEFAULT now();

CREATE INDEX IF NOT EXISTS job_tasks_site ON job_tasks (job_id, site, status);

-- Rejections are counted per job so "crawled 12 pages" can be qualified with
-- "and turned away 4,000 as off-site". A silent cap reads as full coverage.
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS rejections jsonb NOT NULL DEFAULT '{}';

-- Incremental crawl compares against the previous visit. `etag` and
-- `last_modified` come from response headers; `content_hash` is the fallback
-- when a server sends neither, which is common.
ALTER TABLE crawl_state ADD COLUMN IF NOT EXISTS status_code integer;
ALTER TABLE crawl_state ADD COLUMN IF NOT EXISTS unchanged_streak integer NOT NULL DEFAULT 0;

CREATE INDEX IF NOT EXISTS crawl_state_hash ON crawl_state (site, content_hash);

-- ---- apps/api/migrations/003_monitor.sql
-- Monitor: single-URL watches with a check timeline.
--
-- 001 created `monitors`, `monitor_snapshots` and `webhook_deliveries`. This
-- adds what the shipped route needs on top: the sensitivity setting, the last
-- change/error markers, and a per-check row so history can say "checked, not
-- changed" — a timeline of snapshots alone cannot express a quiet check.

ALTER TABLE monitors
  ADD COLUMN IF NOT EXISTS sensitivity    text        NOT NULL DEFAULT 'any',
  ADD COLUMN IF NOT EXISTS last_change_at timestamptz,
  ADD COLUMN IF NOT EXISTS last_error     text,
  ADD COLUMN IF NOT EXISTS updated_at     timestamptz NOT NULL DEFAULT now();

CREATE TABLE IF NOT EXISTS monitor_checks (
  id           bigserial   PRIMARY KEY,
  monitor_id   uuid        NOT NULL REFERENCES monitors(id) ON DELETE CASCADE,
  snapshot_id  bigint      REFERENCES monitor_snapshots(id) ON DELETE SET NULL,
  checked_at   timestamptz NOT NULL DEFAULT now(),
  changed      boolean     NOT NULL DEFAULT false,
  reason       text        NOT NULL,   -- first | changed | unchanged | filtered | trigger_not_met | error
  diff         jsonb,
  error        text
);

CREATE INDEX IF NOT EXISTS monitor_checks_timeline ON monitor_checks (monitor_id, checked_at DESC);

-- Monitor deliveries never carry a job id; the dedupe key already scopes them.
ALTER TABLE webhook_deliveries
  ADD COLUMN IF NOT EXISTS response_status integer;

-- ---- apps/api/migrations/004_monitor_claims.sql
-- Monitor claims carry a timestamp.
--
-- A claim is `next_check_at = NULL`. Without knowing when it was taken, a
-- second API process starting up cannot tell a crashed check from one that is
-- running right now, and re-arms both. `claimed_at` lets it release only the
-- claims old enough to be dead.

ALTER TABLE monitors
  ADD COLUMN IF NOT EXISTS claimed_at timestamptz;

-- ---- apps/api/migrations/005_provider_keys.sql
-- Provider keys: a caller's own LLM credentials, stored against their Helix
-- API key. When present, every LLM-backed call made with that key uses these
-- instead of the instance's environment credentials.

CREATE TABLE IF NOT EXISTS provider_keys (
  api_key_id     uuid        NOT NULL REFERENCES api_keys(id) ON DELETE CASCADE,
  provider       text        NOT NULL CHECK (provider IN ('anthropic', 'openai', 'gemini', 'openrouter')),
  key_ciphertext bytea       NOT NULL,
  key_iv         bytea       NOT NULL,
  key_last4      text        NOT NULL,
  model          text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (api_key_id, provider)
);

-- ---- apps/api/migrations/006_instance_settings.sql
-- Instance settings: operator-editable configuration for a self-hosted Helix.
--
-- The environment remains the source of defaults. A row here is an *override*
-- applied on top of it, so an instance with an empty table behaves exactly as
-- it does today and deleting a row reverts to the environment value.
--
-- Only settings the operator may safely change are ever written here; the
-- application decides which those are, and refuses the rest.

CREATE TABLE IF NOT EXISTS instance_settings (
  key         text        PRIMARY KEY,
  value       jsonb       NOT NULL,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  updated_by  text
);

-- Key versioning for stored secrets.
--
-- Rotating the encryption key previously made every stored provider key
-- undecryptable: `decryptSecret` takes one key and the rows carry no marker
-- saying which key encrypted them. Recording the version lets an instance hold
-- the old key alongside the new one and re-encrypt row by row.
--
-- Existing rows were encrypted under the original key, which is version 1.
ALTER TABLE provider_keys add column if not exists key_version integer NOT NULL DEFAULT 1;

-- The encryption keys themselves are never stored here. This records only which
-- version is current and when it was promoted, so a rotation is auditable and a
-- half-finished one is visible rather than silent.
CREATE TABLE IF NOT EXISTS encryption_key_versions (
  version     integer     PRIMARY KEY,
  fingerprint text        NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  retired_at  timestamptz
);

-- ---- apps/api/migrations/007_local_providers.sql
-- Local runtimes as stored providers: Ollama, vLLM and OpenAI-compatible
-- servers are reachable per-caller, not just through the instance-wide
-- OPENAI_COMPATIBLE_BASE_URL. A local runtime is identified by a base URL
-- rather than a key — most need no credential at all — so the row now
-- carries either, instead of a key being mandatory for every provider.

ALTER TABLE provider_keys DROP CONSTRAINT IF EXISTS provider_keys_provider_check;
alter table provider_keys drop constraint if exists provider_keys_provider_check;
alter table provider_keys add constraint provider_keys_provider_check
  CHECK (provider IN ('anthropic', 'openai', 'gemini', 'openrouter', 'ollama', 'vllm', 'openai-compatible'));

ALTER TABLE provider_keys add column if not exists base_url text;

ALTER TABLE provider_keys ALTER COLUMN key_ciphertext DROP NOT NULL;
ALTER TABLE provider_keys ALTER COLUMN key_iv DROP NOT NULL;
ALTER TABLE provider_keys ALTER COLUMN key_last4 DROP NOT NULL;

alter table provider_keys drop constraint if exists provider_keys_key_or_base_url;
alter table provider_keys add constraint provider_keys_key_or_base_url
  CHECK (key_ciphertext IS NOT NULL OR base_url IS NOT NULL);

-- Rollback:
-- ALTER TABLE provider_keys DROP CONSTRAINT IF EXISTS provider_keys_key_or_base_url;
-- DELETE FROM provider_keys WHERE provider IN ('ollama', 'vllm', 'openai-compatible');
-- ALTER TABLE provider_keys ALTER COLUMN key_ciphertext SET NOT NULL;
-- ALTER TABLE provider_keys ALTER COLUMN key_iv SET NOT NULL;
-- ALTER TABLE provider_keys ALTER COLUMN key_last4 SET NOT NULL;
-- ALTER TABLE provider_keys DROP COLUMN base_url;
-- ALTER TABLE provider_keys DROP CONSTRAINT IF EXISTS provider_keys_provider_check;
-- ALTER TABLE provider_keys ADD CONSTRAINT provider_keys_provider_check
--   CHECK (provider IN ('anthropic', 'openai', 'gemini', 'openrouter'));

-- ---- apps/api/migrations/008_monitor_json_options.sql
-- Field-level JSON diffs on the check path.
--
-- `json_options` mirrors /scrape's jsonOptions: a schema (and optional
-- prompt/provider/model) that a changed page's markdown is run through via
-- helix-extract /structured, before and after, so the check can report which
-- fields changed rather than a text diff of serialized JSON. Null means the
-- monitor never asks for structured extraction and only text diffs run.
--
-- Rollback: `ALTER TABLE monitors DROP COLUMN IF EXISTS json_options;` --
-- existing monitors have none set, so this is safe to add and remove without
-- touching data outside the new column.

ALTER TABLE monitors
  ADD COLUMN IF NOT EXISTS json_options jsonb;

-- ---- apps/api/migrations/009_uptime_samples.sql
-- Uptime samples for the public status page.
--
-- One row per service per sampler tick (`src/status/sampler.ts`, every 60s),
-- reusing the same checks `/health` runs so the two never drift. `days`
-- bucketing and `okPct`/`p50Ms` are computed from this table at read time by
-- `GET /status/history`; nothing here is pre-aggregated. 90 days of samples at
-- one row per service per minute is a few million rows at most — small enough
-- that the sampler prunes anything older on every tick rather than needing a
-- separate job.
--
-- Rollback: `DROP TABLE IF EXISTS uptime_samples;` — nothing else reads it.

CREATE TABLE IF NOT EXISTS uptime_samples (
  service text NOT NULL,
  sampled_at timestamptz NOT NULL DEFAULT now(),
  ok boolean NOT NULL,
  latency_ms integer
);

CREATE INDEX IF NOT EXISTS uptime_samples_service_sampled_at_idx
  ON uptime_samples (service, sampled_at DESC);

-- ---- apps/api/migrations/010_task_leases.sql
-- Crawl task leases.
--
-- 002 made the frontier durable, but a claim was only half a lease. A worker
-- that exits cleanly calls `release()` and returns its claims to the queue; a
-- worker that is SIGKILLed, OOM-killed or loses its container does not, and
-- those rows sit at 'running' with a `claimed_at` nobody ever reads again. The
-- crawl then finishes reporting fewer pages than it queued, with no failure row
-- to explain the difference — the worst shape a bug can take here, because it
-- looks like a completed crawl.
--
-- A lease is a claim with an expiry. `lease_expires_at` is set when a task is
-- claimed and extended while the worker still holds it; any task whose lease is
-- in the past is reclaimable by any worker, whether or not the process that
-- took it still exists. That is the difference between an 'in_progress' flag
-- and a visibility timeout: the flag needs someone to clear it, the timeout
-- clears itself.
--
-- `attempts` already existed and was only ever incremented on failure. Reclaim
-- increments it too, so a URL that repeatedly kills its worker is visible as a
-- task with rising attempts rather than an invisible retry loop.
--
-- Rollback:
--   DROP INDEX IF EXISTS job_tasks_reclaimable;
--   ALTER TABLE job_tasks DROP COLUMN IF EXISTS lease_expires_at;
--   ALTER TABLE job_tasks DROP COLUMN IF EXISTS max_attempts;
-- Nothing else reads either column; the worker falls back to the pre-lease
-- behaviour, which loses interrupted tasks exactly as it did before.

ALTER TABLE job_tasks ADD COLUMN IF NOT EXISTS lease_expires_at timestamptz;

-- Bounded here rather than in code so a reclaim loop cannot outlive a migration
-- that changes its mind. A task reclaimed this many times is recorded as failed
-- instead of being handed to a fourth worker to kill.
ALTER TABLE job_tasks ADD COLUMN IF NOT EXISTS max_attempts integer NOT NULL DEFAULT 3;

-- The partial index carries the whole reclaim query: running tasks are a small
-- fraction of a large crawl, and a full scan of job_tasks per sweep would make
-- the reclaim more expensive than the work it recovers.
CREATE INDEX IF NOT EXISTS job_tasks_reclaimable
  ON job_tasks (lease_expires_at)
  WHERE status = 'running';

-- ---- apps/api/migrations/011_request_usage.sql
-- Per-key request usage, rolled up by hour.
--
-- Nothing recorded before this file could answer "how many requests did this
-- key make". `jobs` is written by exactly two routes (crawl and batch_scrape);
-- scrape, parse, search, map, metadata and interact are synchronous and record
-- nothing at all, so a count derived from `jobs` would under-report by most of
-- the product and look like a working chart while doing it. `last_used_at` on
-- api_keys is a single timestamp with no history behind it, and the rate
-- limiter's buckets are in-memory and per-process — they vanish on restart and
-- disagree between nodes.
--
-- Hourly buckets rather than a row per request: a row per request is unbounded
-- write amplification on the hot path for a number nobody reads at that
-- resolution, and it would need its own retention job. One UPSERT per key per
-- endpoint per status-class per hour keeps the table small enough that the
-- dashboard's range queries stay index-only.
--
-- `bucket_start` is truncated to the hour in UTC by the writer, so the primary
-- key doubles as the upsert conflict target and no separate unique index is
-- needed.
--
-- Rollback:
--   DROP TABLE IF EXISTS request_usage;
-- The recorder tolerates its own table being absent (it is fire-and-forget and
-- swallows errors), so dropping this leaves the API serving traffic exactly as
-- it did before, with the usage endpoint reporting unavailable.

CREATE TABLE IF NOT EXISTS request_usage (
  api_key_id   uuid        NOT NULL REFERENCES api_keys(id) ON DELETE CASCADE,
  bucket_start timestamptz NOT NULL,
  -- The route family, not the raw path: `/v1/scrape` and `/v1/jobs/:id` are
  -- products, `/v1/jobs/9f3c…` is cardinality. Normalised by the recorder.
  endpoint     text        NOT NULL,
  -- 2xx | 4xx | 429 | 5xx. 429 is split out of 4xx because "am I being rate
  -- limited" is the question the headroom panel exists to answer, and it is
  -- invisible once it is averaged into client errors.
  status_class text        NOT NULL,
  requests     bigint      NOT NULL DEFAULT 0,
  PRIMARY KEY (api_key_id, bucket_start, endpoint, status_class)
);

-- The dashboard's only query shape: one key, a time range, grouped. Leading
-- api_key_id then bucket_start means the range scan touches only that key's
-- rows rather than every key's hour.
CREATE INDEX IF NOT EXISTS request_usage_key_time
  ON request_usage (api_key_id, bucket_start DESC);

-- Retention. Ninety days of hourly buckets is ~2k rows per key per endpoint
-- family and bounds the table without a separate job: the sweep runs from the
-- same place the crawl expiry sweep does.
CREATE INDEX IF NOT EXISTS request_usage_expiry
  ON request_usage (bucket_start);

-- ---- apps/api/migrations/012_job_leases.sql
-- Crawl job leases.
--
-- 010 gave `job_tasks` a visibility timeout, and it works: a worker that is
-- SIGKILLed leaves its tasks reclaimable, and `reclaimExpired` returns them to
-- the queue on the next sweep. The parent `jobs` row never got the same
-- treatment. It is flipped to 'running' when claimed and reset only on the
-- graceful shutdown path, so a hard kill leaves the job at 'running' with no
-- process behind it.
--
-- That is worse than the task-level bug 010 fixed, because both escapes are
-- closed at once: `#claimJob` selects `status = 'queued'`, so no worker will
-- ever pick the job up again, and `POST /crawl {resume}` refuses it with
-- `already_running` precisely because it is 'running'. The documented recovery
-- path is shut against the exact failure it exists for. The tasks are
-- reclaimable and nothing is left to claim them; the crawl polls as 'running'
-- with `started_at` set, forever, and no failure row explains it.
--
-- Same remedy as 010, one level up: a claim becomes a lease. `lease_expires_at`
-- is set when a job is claimed and extended while the worker still holds it.
-- A job whose lease is in the past is claimable by any worker, whether or not
-- the process that took it still exists — a timeout clears itself, a flag needs
-- someone alive to clear it.
--
-- No `max_attempts` counterpart here. A poison URL kills a task and 010 already
-- bounds that; a job is only ever reclaimed because its worker died, and
-- capping job reclaims would strand long crawls on an unlucky restart.
--
-- Rollback:
--   DROP INDEX IF EXISTS jobs_reclaimable;
--   ALTER TABLE jobs DROP COLUMN IF EXISTS lease_expires_at;
-- The claim predicate falls back to 'queued'-only, which loses interrupted
-- jobs exactly as it did before.

ALTER TABLE jobs ADD COLUMN IF NOT EXISTS lease_expires_at timestamptz;

-- Mirrors job_tasks_reclaimable: running jobs are a small fraction of the
-- table, and a full scan per claim would cost more than the work it recovers.
CREATE INDEX IF NOT EXISTS jobs_reclaimable
  ON jobs (lease_expires_at)
  WHERE status = 'running';

-- ---- apps/api/migrations/013_job_warnings.sql
-- Job warnings.
--
-- A crawl could finish 'completed' with pages it fetched and never recorded:
-- a task row left 'queued' or 'running', or a result dropped because this
-- worker no longer owned the row. Nothing on the job said so, so a partial
-- crawl read as a whole one. The worker now checks `job_tasks` at finish and
-- names any gap here; a job with nothing recorded and rows left over is
-- 'failed' instead.
--
-- Rollback:
--   ALTER TABLE jobs DROP COLUMN IF EXISTS warnings;

ALTER TABLE jobs ADD COLUMN IF NOT EXISTS warnings jsonb NOT NULL DEFAULT '[]';

-- ============================================================================
-- schema_migrations seed (what apps/api/src/db/migrate.ts would have recorded)
-- ============================================================================

CREATE TABLE IF NOT EXISTS schema_migrations (
  filename    text PRIMARY KEY,
  checksum    text        NOT NULL,
  applied_at  timestamptz NOT NULL DEFAULT now()
);
INSERT INTO schema_migrations (filename, checksum) VALUES
  ('001_init.sql', 'f4746eb0723599256e32b5cc19f302542e1b0dc7d9c282c95988c8a752b417d5'),
  ('002_frontier.sql', '3856261e300d15130ef368a33eb1ac2f68384221871eb7906202794058a7d7f8'),
  ('003_monitor.sql', 'b5facfa8334900ad8b0f08885ffa6bd8670978f735b72cd8254540d4c5f8545b'),
  ('004_monitor_claims.sql', '9978e32bc5d32025e527c8ee916ab780a9007e6832b4336136000a6fdfe1380b'),
  ('005_provider_keys.sql', '181c528ba517261e00d2af068a6972efebfe6d589a47ae24eab097b493f68eaa'),
  ('006_instance_settings.sql', '69f594bbcac665266bb9bf6b4901e9d8b9097073269485882f796f9c760cc475'),
  ('007_local_providers.sql', 'fbd014e71586b7626e6208b4881cdbe17d9325efca6c15b2ed3f050c425fdcd9'),
  ('008_monitor_json_options.sql', '28d1ca216258b985f27252b413d7511acbb18ccbb8d151c21f3b1b8a5323447a'),
  ('009_uptime_samples.sql', '44f4a473d4d6fe3bbe89df261c29a5fa9af0c476ba9a7b33fd7442fae1245860'),
