-- ============================================================================
-- Hosted migrations
-- ============================================================================

-- ---- supabase/migrations/0001_hosted_identity.sql
-- Hosted identity on top of the API's own schema.
--
-- ONE DATABASE. The hosted Helix API runs apps/api/migrations/*.sql against
-- this Supabase project at boot, so `api_keys` here IS the table the API
-- authenticates against. The dashboard mints a key by inserting the same
-- sha256 row the API would, and the key is valid on the next request — no
-- mirror, no `/internal/keys` sync, no second copy of anything.
--
-- The 2026-08-29 removal of Supabase was about duplication: the hosted half
-- kept its own profiles, api_keys, runs and usage beside the instance's. This
-- file adds exactly one thing the API does not know about — who owns a key —
-- and nothing the instance already records.
--
-- Requires the API migrations to have run first (api_keys, jobs, monitors).

do $$ begin
  if to_regclass('public.api_keys') is null then
    raise exception 'api_keys is missing: run apps/api/migrations first (or apply supabase/schema.sql to a fresh project)';
  end if;
end $$;

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------- profiles
--
-- Identity lives in Clerk. This row exists so that keys can reference a stable
-- uuid rather than a Clerk id string, and so a user deleted in Clerk cascades
-- everything they owned.

create table if not exists profiles (
  id             uuid primary key default gen_random_uuid(),
  clerk_user_id  text unique not null,
  email          text not null,
  name           text,
  avatar_url     text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create or replace function touch_updated_at() returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

drop trigger if exists profiles_touch on profiles;
create trigger profiles_touch before update on profiles
  for each row execute function touch_updated_at();

-- ---------------------------------------------------------------- key ownership

alter table api_keys add column if not exists profile_id uuid references profiles(id) on delete cascade;
create index if not exists api_keys_profile_idx on api_keys (profile_id) where revoked_at is null;

-- ---------------------------------------------------------------- Clerk claim
--
-- Clerk is configured as a third-party auth provider on the Supabase project,
-- so a Clerk session token presented to PostgREST lands here as
-- request.jwt.claims with the Clerk user id in `sub`. `nullif` guards the
-- empty-string setting PostgREST uses on some unauthenticated requests, which
-- would otherwise raise on the jsonb cast instead of matching nothing.

create or replace function current_clerk_user_id() returns text
language sql stable as $$
  select coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub',
    ''
  )
$$;

create or replace function current_profile_id() returns uuid
language sql stable as $$
  select id from profiles where clerk_user_id = current_clerk_user_id()
$$;

-- ---------------------------------------------------------------- RLS
--
-- Every table in `public` is reachable through the Data API once the
-- anon/authenticated roles hold grants, so RLS is on for all of them. The API
-- connects as the table owner and is unaffected. Policies exist only where a
-- signed-in browser should read directly; everything else stays server-only.

alter table profiles enable row level security;
alter table api_keys enable row level security;
alter table jobs enable row level security;
alter table job_tasks enable row level security;
alter table documents enable row level security;
alter table fetch_failures enable row level security;
alter table crawl_state enable row level security;
alter table monitors enable row level security;
alter table monitor_snapshots enable row level security;
alter table monitor_checks enable row level security;
alter table webhook_deliveries enable row level security;
alter table enrich_results enable row level security;
alter table provider_keys enable row level security;
alter table instance_settings enable row level security;
alter table encryption_key_versions enable row level security;
alter table schema_migrations enable row level security;
do $$ begin
  if to_regclass('public.chunks') is not null then
    execute 'alter table chunks enable row level security';
  end if;
end $$;

drop policy if exists profiles_select_self on profiles;
create policy profiles_select_self
  on profiles for select
  to authenticated using (clerk_user_id = current_clerk_user_id());

drop policy if exists profiles_update_self on profiles;
create policy profiles_update_self
  on profiles for update
  to authenticated
  using (clerk_user_id = current_clerk_user_id())
  with check (clerk_user_id = current_clerk_user_id());

-- Keys are listed directly; they are minted and revoked by the server route,
-- which is the only place the plaintext ever exists.
drop policy if exists api_keys_select_own on api_keys;
create policy api_keys_select_own
  on api_keys for select
  to authenticated using (profile_id = current_profile_id());

drop policy if exists jobs_select_own on jobs;
create policy jobs_select_own
  on jobs for select
  to authenticated using (
    api_key_id in (select id from api_keys where profile_id = current_profile_id())
  );

drop policy if exists monitors_select_own on monitors;
create policy monitors_select_own
  on monitors for select
  to authenticated using (
    api_key_id in (select id from api_keys where profile_id = current_profile_id())
  );

-- The hash column must never reach a browser, even the key owner's. A
-- column-level REVOKE is a no-op while the table-level grant Supabase's default
-- privileges hand out still stands, so the table grant goes and the readable
-- columns come back one by one.
revoke all on api_keys from anon, authenticated;
grant select (id, name, key_prefix, rate_limit, profile_id, created_at, last_used_at, revoked_at)
  on api_keys to authenticated;

-- ---- supabase/migrations/0003_onboarding.sql
-- Onboarding answers on the profile (WEBSITE.md §6.2).
--
-- Five questions, asked once at /onboarding, re-editable later under
-- Settings → Preferences. Four of the five are optional and skippable, so
-- every column is nullable and the arrays default empty rather than null —
-- a skipped step and an unanswered one are the same thing to every reader,
-- and `selected_endpoints` is iterated by the sidebar and the SKILL.md
-- generator, which should not have to null-check before looping.
--
-- `onboarding_completed_at` is the gate: middleware sends a signed-in user
-- with a null here to /onboarding. It is set when step 5 submits, including
-- when every step was skipped, so skipping is a completion and does not trap
-- the user in a loop.

alter table profiles add column if not exists role                text;
alter table profiles add column if not exists use_cases           text[] not null default '{}';
alter table profiles add column if not exists llm_provider        text;
alter table profiles add column if not exists deploy_intent       text;
alter table profiles add column if not exists selected_endpoints  text[] not null default '{}';
alter table profiles add column if not exists onboarding_completed_at timestamptz;

-- The single-select answers are closed vocabularies. Constraining them here
-- means a typo in a client payload fails at the boundary rather than becoming
-- a value the dashboard silently never matches. Null stays legal (skipped).
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_role_check') then
    alter table profiles add constraint profiles_role_check
      check (role is null or role in ('engineer', 'founder', 'researcher', 'data_ml', 'other'));
  end if;

  if not exists (select 1 from pg_constraint where conname = 'profiles_llm_provider_check') then
    alter table profiles add constraint profiles_llm_provider_check
      check (llm_provider is null or llm_provider in ('anthropic', 'openai', 'google', 'openrouter', 'local', 'unsure'));
  end if;

  if not exists (select 1 from pg_constraint where conname = 'profiles_deploy_intent_check') then
    alter table profiles add constraint profiles_deploy_intent_check
      check (deploy_intent is null or deploy_intent in ('hosted', 'self_host', 'both'));
  end if;
end $$;

-- The multi-selects are checked by containment so an unknown element is
-- rejected without pinning the column to a fixed length.
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_use_cases_check') then
    alter table profiles add constraint profiles_use_cases_check
      check (use_cases <@ array['agent_tools', 'research_pipeline', 'rag_search', 'monitoring', 'enrichment', 'internal_tooling']::text[]);
  end if;

  if not exists (select 1 from pg_constraint where conname = 'profiles_selected_endpoints_check') then
    alter table profiles add constraint profiles_selected_endpoints_check
      check (selected_endpoints <@ array['scrape', 'parse', 'search', 'crawl', 'interact', 'monitor']::text[]);
  end if;
end $$;

-- profiles_update_self (0001) already lets a signed-in browser update its own
-- row, and these columns are inside it. The wizard nonetheless writes through
-- a server action with the service role, because completing onboarding also
-- mints the first API key, which RLS deliberately cannot do.

-- ---- supabase/migrations/0005_onboarding_attribution.sql
-- Where the user heard about Helix, asked during onboarding.
--
-- A closed vocabulary like the other single-selects, plus one free-text field
-- that is ONLY read when the answer is 'other'. Two columns rather than one
-- because a free-text column that sometimes holds a vocabulary value and
-- sometimes holds prose cannot be grouped without cleaning it first, and the
-- entire point of asking is to count the answers.

alter table profiles add column if not exists heard_from        text;
alter table profiles add column if not exists heard_from_detail text;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_heard_from_check') then
    alter table profiles add constraint profiles_heard_from_check
      check (heard_from is null or heard_from in (
        'search', 'social', 'friend', 'hn', 'github', 'blog', 'ai_assistant', 'other'
      ));
  end if;

  -- The detail is a note on 'other', never a second answer. Bounding it here
  -- keeps a paste-bomb out of the column, and pinning it to 'other' stops the
  -- free text from quietly becoming the real answer for a categorised row —
  -- which would put the count and the prose out of step.
  if not exists (select 1 from pg_constraint where conname = 'profiles_heard_from_detail_check') then
    alter table profiles add constraint profiles_heard_from_detail_check
      check (
        heard_from_detail is null
        or (heard_from = 'other' and char_length(heard_from_detail) <= 200)
      );
  end if;
end $$;

-- ---- supabase/migrations/0006_dashboard_keys.sql
-- The proxy's own key per profile (WEBSITE.md — hosted playground/providers).
--
-- Every client caller in the dashboard reads its API key from a browser-held
-- ApiKeyProvider, which hosted mode deliberately does not mount (a signed-in
-- user has not minted one yet). The fix is server-side proxy routes under
-- /api/app/*, and they need something to call the Helix API WITH. api_keys
-- only stores a sha256 hash — by design, the plaintext is shown once at
-- creation and is not recoverable — so there is no user key to read back.
--
-- Each profile instead gets exactly one dedicated api_keys row, minted lazily
-- on first proxy use via the same insert lib/profiles.ts#createApiKey already
-- does (WEBSITE.md's "no mirror" model: this IS a real key the API
-- authenticates). Its plaintext is encrypted at rest with
-- HELIX_KEY_ENCRYPTION_KEY (lib/keys.ts's AES-256-GCM helpers, provisioned but
-- unused until now) and decrypted only inside a route handler; it never
-- reaches the browser. Storing it on profiles rather than a new table keeps
-- the 1:1 relationship explicit and gives BYOK provider config (provider_keys,
-- keyed on api_key_id) somewhere to live exactly as it already does in
-- self-host: scoped to the key a request actually authenticates with.
--
-- Rollback: drop the two columns. Any dashboard key already minted stays live
-- in api_keys (it is a real key) but becomes unreachable by the proxy; either
-- revoke those rows by name ('Dashboard (internal)') or leave them — they cost
-- nothing idle.

alter table profiles add column if not exists dashboard_key_id         uuid references api_keys(id) on delete set null;
alter table profiles add column if not exists dashboard_key_ciphertext bytea;
alter table profiles add column if not exists dashboard_key_iv         bytea;

-- Never exposed to a browser, including the key owner's own session — same
-- posture as api_keys.key_hash in 0001.
revoke all on profiles from anon, authenticated;
grant select (id, clerk_user_id, email, name, avatar_url, created_at, updated_at,
              role, use_cases, llm_provider, deploy_intent, selected_endpoints,
              heard_from, heard_from_detail, onboarding_completed_at)
  on profiles to authenticated;
grant update (name, avatar_url, role, use_cases, llm_provider, deploy_intent,
              selected_endpoints, heard_from, heard_from_detail, onboarding_completed_at)
  on profiles to authenticated;

-- ---- supabase/migrations/0007_request_usage_rls.sql
-- RLS for request_usage (apps/api/migrations/011_request_usage.sql).
--
-- 0001 turned row level security on for every table in `public` and explained
-- why: once the anon/authenticated roles hold Supabase's default grants, every
-- table is reachable through the Data API. A table added by a later API
-- migration is not covered by that statement, so it arrives readable by any
-- signed-in browser — and request_usage is a per-key traffic log, which is
-- exactly the kind of thing that should not be.
--
-- No policy is added. The dashboard reads this table through the service-role
-- client in app/api/app/usage/route.ts, which bypasses RLS; a browser has no
-- business querying it directly, and RLS with no policy denies everything.
-- That is the intended posture, not an omission.
--
-- Requires 011 to have run. The API applies its own migrations against this
-- database at boot, so a deployment that has not restarted the API yet will
-- not have the table: the guard below skips rather than failing the whole
-- migration, and the next run picks it up.
--
-- Rollback:
--   ALTER TABLE request_usage DISABLE ROW LEVEL SECURITY;
--   -- and re-grant only if something other than the service role needs it.

do $$ begin
  if to_regclass('public.request_usage') is not null then
    execute 'alter table request_usage enable row level security';
    execute 'revoke all on request_usage from anon, authenticated';
  end if;
end $$;

-- ---- supabase/migrations/0008_browser_role_hardening.sql
-- Close the Supabase Data API surface.
--
-- Supabase grants `anon` and `authenticated` full DML on every table in
-- `public` by default, and PostgREST exposes them at /rest/v1 to anyone holding
-- the publishable key — which ships in the browser bundle and is not a secret.
-- RLS is what makes that grant inert: a table with RLS on and no policy denies
-- everything, which is why most of this schema was already safe.
--
-- Two tables were not. `request_usage` (011) and `uptime_samples` (009) are
-- created by the API's own migration runner, which has no reason to know about
-- Supabase's roles, so they were created with RLS off. Verified against the live
-- project on 2026-09-04: both were readable with the publishable key, and an
-- anonymous INSERT into `uptime_samples` was refused only by a not-null
-- constraint (23502) rather than by any permission check — an authorized write
-- that would have poisoned the public status page.
--
-- This migration governs the browser surface only. It does NOT constrain the
-- API, which connects as `postgres` and holds BYPASSRLS; the /v1/* tenant
-- boundary is enforced in application code (HELIX_MULTI_TENANT, 1.11.0). Making
-- RLS bind the API needs a non-BYPASSRLS role and a per-request transaction
-- scope, which is a separate and much larger change.
--
-- Rollback: `alter table <t> disable row level security;` per table below, and
-- drop the two policies. Nothing here changes data.

-- ---------------------------------------------------------------- deny by default

alter table request_usage  enable row level security;
alter table uptime_samples enable row level security;

-- REVOKE rather than rely on RLS alone. Defence in depth: a policy added later
-- for an unrelated reason should not silently re-open write access, and a grant
-- nobody uses is a grant nobody audits. The API is unaffected — it is the table
-- owner and does not consult these grants.
revoke all on request_usage  from anon, authenticated;
revoke all on uptime_samples from anon, authenticated;

-- ---------------------------------------------------------------- the status page

-- `/status` is public and reads uptime history through the API, not through
-- PostgREST, so no browser role needs access. Left with no policy: RLS on plus
-- no policy denies every role that does not bypass it.

-- ---------------------------------------------------------------- force

-- FORCE makes a table's owner subject to its own policies. It does NOT affect a
-- BYPASSRLS role, so this does not constrain the API today; it is here so that
-- pointing the API at a non-BYPASSRLS role later is a connection-string change
-- rather than another migration. Applied only to the two tables above, because
-- forcing it on tables the API writes through owner privilege would break them
-- the moment that role changes.
alter table request_usage  force row level security;
alter table uptime_samples force row level security;
